import { useEffect, useState } from "react";
import axios from "axios";

export default function Submissions() {
  const [subs, setSubs] = useState([]);
  const [grades, setGrades] = useState({});
  const [remarks, setRemarks] = useState({});
  const [autoGrades, setAutoGrades] = useState({}); // ✅ NEW (store auto grade per submission)

  useEffect(() => {
    fetchSubs();
  }, []);

  const fetchSubs = () => {
    axios
      .get("/api/submissions/1")
      .then((res) => setSubs(res.data))
      .catch((err) => console.log(err));
  };

  // ✅ AUTO GRADE FUNCTION
  const calculateGrade = (marks) => {
    if (marks >= 85) return "A";
    if (marks >= 70) return "B";
    if (marks >= 50) return "C";
    return "D";
  };

  const submitGrade = async (id) => {
    try {
      await axios.post("/api/submissions/grade", {
        submission_id: id,
        marks: grades[id],
        remarks: remarks[id],
        grade: autoGrades[id], // ✅ SEND AUTO GRADE
      });

      alert("Graded ✅");
      fetchSubs();
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-6">
        📥 Student Submissions
      </h1>

      {subs.length === 0 ? (
        <p className="text-gray-500">No submissions yet</p>
      ) : (
        subs.map((s) => (
          <div
            key={s.submission_id}
            className="bg-white p-4 mb-4 rounded shadow border"
          >
            <h2 className="font-semibold">
              {s.assignment_title}
            </h2>

            <p className="text-sm text-gray-600">
              📘 {s.course_name}
            </p>

            <p className="text-sm text-gray-600">
              👨‍🎓 {s.student_name}
            </p>

            <p className="mt-2">
              📝 {s.content}
            </p>

            <p className="text-xs text-gray-500 mt-2">
              Submitted on:{" "}
              {new Date(s.submitted_at).toLocaleString()}
            </p>

            {/* ✅ GRADING SECTION */}
            <div className="mt-3">
              <input
                type="number"
                placeholder="Marks"
                value={grades[s.submission_id] || ""}
                onChange={(e) => {
                  const value = e.target.value;

                  // update marks
                  setGrades({
                    ...grades,
                    [s.submission_id]: value,
                  });

                  // ✅ AUTO CALCULATE GRADE
                  setAutoGrades({
                    ...autoGrades,
                    [s.submission_id]: calculateGrade(Number(value)),
                  });
                }}
                className="border p-1 mr-2 w-24 rounded"
              />

              <input
                type="text"
                placeholder="Remarks"
                value={remarks[s.submission_id] || ""}
                onChange={(e) =>
                  setRemarks({
                    ...remarks,
                    [s.submission_id]: e.target.value,
                  })
                }
                className="border p-1 mr-2 rounded"
              />

              <button
                onClick={() => submitGrade(s.submission_id)}
                className="bg-green-500 text-white px-2 py-1 rounded"
              >
                Submit Grade
              </button>
            </div>

            {/* ✅ SHOW GRADE IF EXISTS */}
            {s.marks && (
              <p className="text-green-600 mt-2">
                ✔ Marks: {s.marks} | {s.remarks} | Grade: {s.grade}
              </p>
            )}
          </div>
        ))
      )}
    </div>
  );
}
